<?php
require $argv[1].'/shared-cards/shared-cards.php';$notes=json_decode(file_get_contents($argv[2]),true);$cards=[];foreach($notes as $i=>$n){foreach(['he-en','en-he'] as $dir){$frames=[];foreach(['front','back'] as $side){$doc=\HebleoShared\bridge_document($n['documents'][$dir][$side]);$frames[$side]='<iframe data-hebleo-shared sandbox="allow-scripts" srcdoc="'.htmlspecialchars($doc,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'"></iframe>';}$cards[]=['sourceId'=>$n['id'],'direction'=>$dir,'note_id'=>10+$i,'template_id'=>$dir==='he-en'?20:21,'state'=>'new','front'=>$frames['front'],'back'=>$frames['back'],'review_version'=>str_repeat('a',64),'intervals'=>['again'=>'1m','hard'=>'5m30s','good'=>'10m','easy'=>'8d']];}}file_put_contents($argv[3],json_encode($cards));echo count($cards).' private original-content preview cases';
